def is_tree(edges):
    if len(edges) != len(set(edges)):
        return False

    # Build adjacency list
    adj = {u: [] for u in set(edges)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check if the graph is connected
    visited = set()
    def dfs(node):
        visited.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                dfs(neighbor)

    dfs(next(iter(adj)))

    # Check if the number of edges equals the number of vertices minus one
    return len(edges) == len(adj) - 1
