def find_triplet(numbers, target):
    n = len(numbers)
    if n < 3:
        return []

    # Sort the array to enable two-pointer technique
    numbers.sort()

    for i in range(n - 2):
        # Skip duplicate values for the first element to avoid redundant checks
        if i > 0 and numbers[i] == numbers[i - 1]:
            continue

        left, right = i + 1, n - 1
        current_sum = numbers[i]

        while left < right:
            total = current_sum + numbers[left] + numbers[right]
            if total == target:
                return [numbers[i], numbers[left], numbers[right]]
            elif total < target:
                left += 1
            else:
                right -= 1

    return []
