    """
    Minimize a mathematical expression by combining like terms,
    removing redundant operations, and simplifying fractions.

    Args:
        expr (str): A string representing a mathematical expression.

    Returns:
        str: The minimized expression.
    """
    # Replace all operators with their ASCII codes for easier manipulation
    ops = {'+': 43, '-': 45, '*': 42, '/': 47}
    expr = expr.replace('+', '43').replace('-', '45').replace('*', '42').replace('/', '47')

    # Split the expression into tokens
    tokens = expr.split()

    # Initialize a dictionary to store coefficients for each variable
    coeff = {}

    # Process tokens to build the expression
    for token in tokens:
        if token in ops:
            # Handle binary operations
            if len(tokens) >= 3:
                left, op, right = tokens[0], tokens[1], tokens[2]
                # Convert right operand to integer
                right = int(right)
                # Apply the operation
                if op == '+':
                    coeff[left] = coeff.get(left, 0) + right
                elif op == '-':
                    coeff[left] = coeff.get(left, 0) - right
                elif op == '*':
                    coeff[left] = coeff.get(left, 0) * right
                elif op == '/':
                    coeff[left] = coeff.get(left, 0) / right
            else:
                # Single operator (should not happen in valid input)
                pass
        else:
            # Variable or constant
            if token in coeff:
                coeff[token] += 1
            else:
                coeff[token] = 1

    # Build the result expression
    result = []
    for token in tokens:
        if token in coeff:
            # Combine like terms
            if len(tokens) > 1 and tokens[0] in coeff:
                # If the first token is a variable, combine with the current one
                if tokens[0] in coeff:
                    result.append(str(coeff[tokens[0]] * tokens[0]))
                    del coeff[tokens[0]]
            else:
                result.append(str(coeff[token]))

