def rotated_binary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        mid_val = arr[mid]

        # Check if mid is the target
        if mid_val == target:
            return mid

        # Determine the rotation point
        if mid_val > arr[left]:
            # Target is in the right half
            if target >= mid_val and target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1
        else:
            # Target is in the left half
