def is_valid_expression(expression):
    if not expression:
        return True

    # Mapping from opening bracket to its weight
    weights = {
        '(': 2,
        '{': 3,
        '[': 5
    }

    # Stack to track opening brackets
    stack = []

    for char in expression:
        if char in weights:
            # Opening bracket
            stack.append(char)
        else:
            # Closing bracket
            if not stack:
                return False

            top = stack.pop()
            if weights[top] != weights[char]:
                return False

    # Check if all opening brackets are closed
    return len(stack) == 0
