def findKthLargest(nums, k):
    if k == 1:
        return max(nums)

    # Use a min-heap of size k to keep track of the k largest elements seen so far.
    import heapq
    heap = []
    for num in nums:
        # If heap size exceeds k, remove the smallest element to maintain size k.
        if len(heap) > k:
            heapq.heappop(heap)
        # If num is larger than the smallest in the heap, add it.
        if num > heap[0]:
            heapq.heappush(heap, num)

    # The root of the min-heap is the kth largest element.
    return heap[0]
