def find_closest_exit(grid):
    if not grid or not grid[0]:
        return None

    rows = len(grid)
    cols = len(grid[0])

    # Initialize distance matrix with large values
    dist = [[float('inf')] * cols for _ in range(rows)]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS from all starting points (cells with distance 0)
    from collections import deque

    queue = deque()
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0:
                dist[i][j] = 0
                queue.append((i, j))

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == -1:
                    continue
                if dist[nr][nc] > dist[r][c] + 1:
                    dist[nr][nc] = dist[r][c] + 1
                    queue.append((nr, nc))

