    min_dist = float('inf')
    best_row = -1
    best_col = -1

    for i in range(rows):
        for j in range(cols):
            if dist[i][j] < min_dist:
                min_dist = dist[i][j]
                best_row = i
                best_col = j

    return (best_row, best_col) if min_dist != float('inf') else None
