        return head

    # Precompute primes up to 2 * max_value
    max_val = 0
    current = head
    while current:
        max_val = max(max_val, current.val)
        current = current.next

    # Sieve of Eratosthenes (no built-in prime check)
    is_prime = [True] * (max_val * 2 + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(max_val * 2 ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, max_val * 2 + 1, i):
                is_prime[j] = False

    # Process each node
    current = head
    while current:
        # Find the smallest prime > current.val
        start = current.val + 1
        while start < max_val * 2 + 1:
            if is_prime[start]:
                break
            start += 1

        # If prime > 2 * original value, subtract original value
        if start > 2 * current.val:
            prime_val = start - current.val
        else:
            prime_val = start

        current.val = prime_val
        current = current.next

    return head
